/* valveC.c — settle U(8): the minimum size of a sorting network on 8 channels
 * whose channel 0 occurs in exactly one comparator.
 *
 * agent-0204 · 2026-08-06T13:10Z
 *
 * WHAT IT SEARCHES
 * ----------------
 * The Valve Lemma (commons/findings/agent-0204_valve_decomposition_and_the_
 * price_of_a_degree1_end_20260806T0730Z.md) says a deg(0)=1 sorting network on
 * n channels is exactly  P ; (0,j) ; Q  with P,Q on channels 1..n-1, P placing
 * min(x_1..x_{n-1}) on channel j, and Q sorting  A = R u flip_j(R).  So with
 * m = n-1 this is a search on m channels over reachable-set states with ONE
 * free FLIP move:
 *
 *    FLIP_j : R -> R u flip_j(R)   legal only while channel j carries the
 *                                  minimum of every reachable vector
 *    U(n) = 1 + min #comparators from the full cube to the sorted set
 *               using exactly one FLIP
 *
 * State = 2^m-bit set of reachable 0/1 vectors, held in one unsigned __int128
 * for m <= 7.  (agent-050's bitmask representation, one channel narrower than
 * an n-channel search; the C-engine shape follows agent-060 / agent-0194.)
 *
 * SOUND PRUNES ONLY (an unsound bound manufactures fake NONE answers -- that
 * was my correction C2):
 *   halving : a comparator is at most 2-to-1 on vectors; the target has m+1
 *   touch   : channel c needs a comparator (c,d), d>c, if some reachable v has
 *             a 1 on c where the sorted output has 0, and (e,c), e<c, if some v
 *             has a 0 where the output has 1.  Each comparator supplies at most
 *             one of each, so remaining >= ceil((#low + #high)/2).
 *
 * THEORY-DERIVED PRUNES (each optional, each citable, all proved):
 *   -hub    Corollary V: the valve is (0,1), so in reduced labels the FLIP is
 *           on channel 0 only.  (agent-0169's Lemma AD + deg(0)=1.)
 *   -pmin   Corollary P: every channel 1..n-1 is touched before the valve, so
 *           |P| >= n-2 = m-1: no FLIP before depth m-1.
 *   -kmax K Theorem R: omega(m) >= k, k = #post-FLIP comparators on the hub.
 *           For a target total size T, omega = T-1-S(m), so k <= T-1-S(m).
 *
 * Build:  gcc -O3 -march=native -o valveC valveC.c
 * Controls (MUST pass before any n=8 answer is believed):
 *   ./valveC -n 5 -T 9  -> FOUND      ./valveC -n 5 -T 8  -> NONE
 *   ./valveC -n 6 -T 13 -> FOUND      ./valveC -n 6 -T 12 -> NONE
 *   ./valveC -n 7 -T 16 -> FOUND      ./valveC -n 7 -T 15 -> NONE
 * Target:
 *   ./valveC -n 8 -T 19   (is a SIZE-OPTIMAL deg(0)=1 network possible?)
 *   ./valveC -n 8 -T 20
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

typedef unsigned __int128 u128;
typedef uint64_t u64;

static int m;              /* reduced channels */
static int NV;             /* 2^m vectors */
static u128 CUBE, TARGET;
static int NOPS;
static int opa[32], opb[32];
static u128 ophi[32];
static int opdelta[32];
static u128 flipbad[8], flipzero[8];
static int flipsh[8];
static uint8_t lomask[128], himask[128];   /* per-vector service masks */

static int S_OPT[13] = {0,0,1,3,5,9,12,16,19,25,29,35,39};

/* ---- options ---------------------------------------------------------- */
static int opt_hub = 1;    /* Corollary V: flip only on reduced channel 0 */
static int opt_pmin = 1;   /* Corollary P: no flip before depth m-1 */
static int opt_kmax = -1;  /* Theorem R: cap on post-flip hub comparators */

/* ---- memo: lossy open-addressed table of FAILED (state,flipused,rem) --- */
static int MEMBITS = 26;
static u128 *mk;           /* key */
static uint8_t *mr;        /* rem proved insufficient */
static uint8_t *mf;        /* flip flag + occupied */

static u64 hash128(u128 x, int f) {
    u64 a = (u64)x, b = (u64)(x >> 64);
    u64 h = a * 0x9E3779B97F4A7C15ULL ^ (b + 0x165667B19E3779F9ULL);
    h ^= h >> 29; h *= 0xBF58476D1CE4E5B9ULL; h ^= h >> 32;
    return h ^ (u64)f * 0x94D049BB133111EBULL;
}

static long long nodes = 0, memohit = 0;
static long long node_cap = 0;
static int capped = 0;

/* ---- setup ------------------------------------------------------------ */
static void setup(int mm) {
    m = mm; NV = 1 << m;
    CUBE = (NV == 128) ? ~(u128)0 : (((u128)1 << NV) - 1);
    TARGET = 0;
    for (int k = 0; k <= m; k++) TARGET |= (u128)1 << (NV - (1 << k));
    NOPS = 0;
    for (int a = 0; a < m; a++) for (int b = a + 1; b < m; b++) {
        u128 hi = 0;
        for (int v = 0; v < NV; v++)
            if (((v >> a) & 1) && !((v >> b) & 1)) hi |= (u128)1 << v;
        opa[NOPS] = a; opb[NOPS] = b; ophi[NOPS] = hi;
        opdelta[NOPS] = (1 << b) - (1 << a); NOPS++;
    }
    for (int j = 0; j < m; j++) {
        u128 bad = 0, zero = 0;
        for (int v = 0; v < NV; v++) {
            if ((v >> j) & 1) { if (v != NV - 1) bad |= (u128)1 << v; }
            else zero |= (u128)1 << v;
        }
        flipbad[j] = bad; flipzero[j] = zero; flipsh[j] = 1 << j;
    }
    for (int v = 0; v < NV; v++) {
        int k = __builtin_popcount(v), L = 0, H = 0;
        for (int c = 0; c < m; c++) {
            int want = (k >= m - c), cur = (v >> c) & 1;
            if (cur && !want) L |= 1 << c;
            else if (!cur && want) H |= 1 << c;
        }
        lomask[v] = L; himask[v] = H;
    }
}

static inline int pc128(u128 x) {
    return __builtin_popcountll((u64)x) + __builtin_popcountll((u64)(x >> 64));
}

static int lower_bound(u128 R) {
    int c = pc128(R), t = m + 1, h = 0;
    while (c > t) { c = (c + 1) / 2; h++; }
    int L = 0, H = 0;
    u128 x = R;
    while (x) {
        int i = __builtin_ctzll((u64)x) ;
        if ((u64)x == 0) { i = 64 + __builtin_ctzll((u64)(x >> 64)); }
        L |= lomask[i]; H |= himask[i];
        x &= x - 1;
    }
    int tb = (__builtin_popcount(L) + __builtin_popcount(H) + 1) / 2;
    return h > tb ? h : tb;
}

/* path for witness printing */
static int pth_kind[64], pth_a[64], pth_b[64], pdepth = 0;

static int dfs(u128 R, int rem, int flipused, int depth, int khub) {
    nodes++;
    if (node_cap && nodes > node_cap) { capped = 1; return 0; }
    if (R == TARGET && flipused) return 1;
    if (rem <= 0) return 0;
    if (lower_bound(R) > rem) return 0;

    u64 h = hash128(R, flipused) & (((u64)1 << MEMBITS) - 1);
    if (mf[h] && mk[h] == R && (mf[h] & 2 ? 1 : 0) == flipused && mr[h] >= rem) {
        memohit++; return 0;
    }

    if (!flipused && !(opt_pmin && depth < m - 1)) {
        int jlo = 0, jhi = opt_hub ? 1 : m;
        for (int j = jlo; j < jhi; j++) {
            if (R & flipbad[j]) continue;
            u128 R2 = R | ((R & flipzero[j]) << flipsh[j]);
            if (R2 == R) continue;
            pth_kind[pdepth] = 1; pth_a[pdepth] = j; pdepth++;
            if (dfs(R2, rem, 1, depth, 0)) return 1;
            pdepth--;
            if (capped) return 0;
        }
    }

    /* order comparators by resulting state size */
    int idx[32], sz[32], nc = 0;
    u128 nx[32];
    for (int i = 0; i < NOPS; i++) {
        if (flipused && opt_kmax >= 0 && (opa[i] == 0 || opb[i] == 0)
            && khub + 1 > opt_kmax) continue;
        u128 hit = R & ophi[i];
        if (!hit) continue;
        u128 R2 = (R & ~ophi[i]) | (hit << opdelta[i]);
        idx[nc] = i; nx[nc] = R2; sz[nc] = pc128(R2); nc++;
    }
    for (int i = 1; i < nc; i++)
        for (int j = i; j > 0 && sz[j] < sz[j - 1]; j--) {
            int a = sz[j]; sz[j] = sz[j-1]; sz[j-1] = a;
            a = idx[j]; idx[j] = idx[j-1]; idx[j-1] = a;
            u128 b = nx[j]; nx[j] = nx[j-1]; nx[j-1] = b;
        }
    for (int i = 0; i < nc; i++) {
        int o = idx[i];
        int nk = khub + ((flipused && (opa[o] == 0 || opb[o] == 0)) ? 1 : 0);
        pth_kind[pdepth] = 0; pth_a[pdepth] = opa[o]; pth_b[pdepth] = opb[o]; pdepth++;
        if (dfs(nx[i], rem - 1, flipused, depth + 1, nk)) return 1;
        pdepth--;
        if (capped) return 0;
    }
    if (!capped) { mk[h] = R; mr[h] = rem; mf[h] = 1 | (flipused ? 2 : 0); }
    return 0;
}

int main(int argc, char **argv) {
    int n = 8, T = 19;
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-n")) n = atoi(argv[++i]);
        else if (!strcmp(argv[i], "-T")) T = atoi(argv[++i]);
        else if (!strcmp(argv[i], "-cap")) node_cap = atoll(argv[++i]);
        else if (!strcmp(argv[i], "-membits")) MEMBITS = atoi(argv[++i]);
        else if (!strcmp(argv[i], "-nohub")) opt_hub = 0;
        else if (!strcmp(argv[i], "-nopmin")) opt_pmin = 0;
        else if (!strcmp(argv[i], "-kmax")) opt_kmax = atoi(argv[++i]);
        else if (!strcmp(argv[i], "-autok")) opt_kmax = -2;
    }
    setup(n - 1);
    if (opt_kmax == -2) {           /* Theorem R: k <= T-1-S(m) */
        opt_kmax = T - 1 - S_OPT[m];
        if (opt_kmax < 0) opt_kmax = 0;
    }
    mk = calloc((size_t)1 << MEMBITS, sizeof(u128));
    mr = calloc((size_t)1 << MEMBITS, 1);
    mf = calloc((size_t)1 << MEMBITS, 1);
    if (!mk || !mr || !mf) { fprintf(stderr, "memo alloc failed\n"); return 2; }

    printf("valveC: n=%d m=%d target_total=%d comparators=%d\n", n, m, T, T - 1);
    printf("  prunes: hub-fixed=%d(CorV) pmin=%d(CorP,|P|>=%d) kmax=%d(ThmR) "
           "memo=2^%d\n", opt_hub, opt_pmin, m - 1, opt_kmax, MEMBITS);
    clock_t t0 = clock();
    int found = dfs(CUBE, T - 1, 0, 0, 0);
    double secs = (double)(clock() - t0) / CLOCKS_PER_SEC;
    printf("  result: %s   nodes=%lld  memohits=%lld  %.2fs  %.2fM nodes/s%s\n",
           found ? "FOUND" : (capped ? "CAP-HIT (NOT a proof)" : "NONE (exhaustive)"),
           nodes, memohit, secs, nodes / (secs > 0 ? secs : 1) / 1e6,
           capped ? "  !! CAP" : "");
