#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

typedef uint64_t u64;
#define L 4                      /* 4 limbs = 256 bits = 2^8 vectors */

typedef struct { u64 w[L]; } St;

static int n, NV, NOPS;
static St CUBE, TARGET;
static int opa[32], opb[32], opdelta[32];
static St ophi[32];
static uint8_t lomask[256], himask[256];

/* ---- 256-bit primitives ---------------------------------------------- */
static inline void st_zero(St *a) { for (int i = 0; i < L; i++) a->w[i] = 0; }
static inline int st_eq(const St *a, const St *b) {
    for (int i = 0; i < L; i++) if (a->w[i] != b->w[i]) return 0;
    return 1;
}
static inline void st_setbit(St *a, int k) { a->w[k >> 6] |= (u64)1 << (k & 63); }
static inline int st_getbit(const St *a, int k) { return (a->w[k >> 6] >> (k & 63)) & 1; }
static inline int st_pc(const St *a) {
    int s = 0; for (int i = 0; i < L; i++) s += __builtin_popcountll(a->w[i]); return s;
}
static inline void st_and(St *r, const St *a, const St *b) {
    for (int i = 0; i < L; i++) r->w[i] = a->w[i] & b->w[i];
}
static inline void st_andnot(St *r, const St *a, const St *b) {  /* a & ~b */
    for (int i = 0; i < L; i++) r->w[i] = a->w[i] & ~b->w[i];
}
static inline void st_or(St *r, const St *a, const St *b) {
    for (int i = 0; i < L; i++) r->w[i] = a->w[i] | b->w[i];
}
static inline int st_zerop(const St *a) {
    for (int i = 0; i < L; i++) if (a->w[i]) return 0;
    return 1;
}
/* shift left by d bits (0 <= d < 256) */
static void st_shl(St *r, const St *a, int d) {
    int lw = d >> 6, bt = d & 63;
    for (int i = L - 1; i >= 0; i--) {
        u64 v = 0;
        int src = i - lw;
        if (src >= 0) {
            v = a->w[src] << bt;
            if (bt && src - 1 >= 0) v |= a->w[src - 1] >> (64 - bt);
        }
        r->w[i] = v;
    }
}

/* ---- setup ----------------------------------------------------------- */
static void setup(int nn) {
    n = nn; NV = 1 << n;
    st_zero(&CUBE);
    for (int v = 0; v < NV; v++) st_setbit(&CUBE, v);
    st_zero(&TARGET);
    for (int k = 0; k <= n; k++) st_setbit(&TARGET, NV - (1 << k));
    NOPS = 0;
    for (int a = 0; a < n; a++) for (int b = a + 1; b < n; b++) {
        St hi; st_zero(&hi);
        for (int v = 0; v < NV; v++)
            if (((v >> a) & 1) && !((v >> b) & 1)) st_setbit(&hi, v);
        opa[NOPS] = a; opb[NOPS] = b; ophi[NOPS] = hi;
        opdelta[NOPS] = (1 << b) - (1 << a); NOPS++;
    }
    for (int v = 0; v < NV; v++) {
        int k = __builtin_popcount(v), lo = 0, hi = 0;
        for (int c = 0; c < n; c++) {
            int want = (k >= n - c), cur = (v >> c) & 1;
            if (cur && !want) lo |= 1 << c;
            else if (!cur && want) hi |= 1 << c;
        }
        lomask[v] = lo; himask[v] = hi;
    }
}

static int lower_bound(const St *R) {
    int c = st_pc(R), t = n + 1, h = 0;
    while (c > t) { c = (c + 1) / 2; h++; }
    int lo = 0, hi = 0;
    for (int i = 0; i < L; i++) {
