            int b = __builtin_ctzll(x);
            int v = (i << 6) + b;
            lo |= lomask[v]; hi |= himask[v];
            x &= x - 1;
        }
    }
    int tb = (__builtin_popcount(lo) + __builtin_popcount(hi) + 1) / 2;
    return h > tb ? h : tb;
}

/* ---- memo ------------------------------------------------------------ */
static int MEMBITS = 26;
static St *mk; static uint8_t *mr, *mf;
static u64 hashst(const St *a, int d0) {
    u64 h = 0x9E3779B97F4A7C15ULL ^ (u64)d0 * 0xD1B54A32D192ED03ULL;
    for (int i = 0; i < L; i++) { h ^= a->w[i] + 0x165667B19E3779F9ULL + (h << 6) + (h >> 2); }
    h ^= h >> 29; h *= 0xBF58476D1CE4E5B9ULL; h ^= h >> 32;
    return h;
}

static long long nodes = 0, memohit = 0, node_cap = 0;
static int capped = 0, maxdeg0 = 1;
static int pa[64], pb[64], pd = 0;

static int dfs(St R, int rem, int d0) {
    nodes++;
    if (node_cap && nodes > node_cap) { capped = 1; return 0; }
    if (st_eq(&R, &TARGET)) return d0 == maxdeg0;   /* require EXACT degree */
    if (rem <= 0) return 0;
    if (lower_bound(&R) > rem) return 0;

    u64 h = hashst(&R, d0) & (((u64)1 << MEMBITS) - 1);
