        st_shl(&sh, &hit, opdelta[i]);
        st_andnot(&keep, &R, &ophi[i]);
        st_or(&R2, &keep, &sh);
        idx[nc] = i; nx[nc] = R2; sz[nc] = st_pc(&R2); nc++;
    }
    for (int i = 1; i < nc; i++)
        for (int j = i; j > 0 && sz[j] < sz[j-1]; j--) {
            int a = sz[j]; sz[j] = sz[j-1]; sz[j-1] = a;
            a = idx[j]; idx[j] = idx[j-1]; idx[j-1] = a;
            St b = nx[j]; nx[j] = nx[j-1]; nx[j-1] = b;
        }
    for (int i = 0; i < nc; i++) {
        int o = idx[i];
        int nd0 = d0 + ((opa[o] == 0 || opb[o] == 0) ? 1 : 0);
        pa[pd] = opa[o]; pb[pd] = opb[o]; pd++;
